  ('user-demo-1', 'alex_learner');

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-01', 'owner', 'audio-b1b2-01', '01. The Midnight Bakery on Elm Street (B1-B2)', 'A short creative story about an unusual late-night bakery that brings lonely neighbors together (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-1', 'lesson-audio-b1b2-01', 'owner', 0, 5.9, 'Every Friday at eleven, a warm scent of cinnamon drifted down Elm Street.', 'Mỗi thứ Sáu lúc mười một giờ, mùi hương quế ấm áp lại lan tỏa dọc con phố Elm.', 'scent of cinnamon, drifted down', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-2', 'lesson-audio-b1b2-01', 'owner', 5.9, 11.4, 'Unlike ordinary shops, the corner bakery only unlocked its door after midnight.', 'Không giống những cửa tiệm bình thường, tiệm bánh góc phố chỉ mở cửa sau nửa đêm.', 'ordinary, unlocked', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-3', 'lesson-audio-b1b2-01', 'owner', 11.4, 16.9, 'Daniel, a tired software engineer, finally decided to investigate the glowing window.', 'Daniel, một kỹ sư phần mềm mệt mỏi, cuối cùng quyết định tìm hiểu ô cửa sổ rực sáng ấy.', 'investigate, glowing', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-4', 'lesson-audio-b1b2-01', 'owner', 16.9, 22.4, 'Inside, an elderly baker named Clara was kneading dough with remarkable precision.', 'Bên trong, một thợ làm bánh lớn tuổi tên Clara đang nhào bột với sự chính xác đáng kinh ngạc.', 'kneading dough, remarkable precision', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-5', 'lesson-audio-b1b2-01', 'owner', 22.4, 27.9, 'She explained that night-shift workers rarely had access to freshly baked bread.', 'Bà giải thích rằng những người làm ca đêm hiếm khi có cơ hội thưởng thức bánh mì mới nướng.', 'night-shift, rarely, access', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-6', 'lesson-audio-b1b2-01', 'owner', 27.9, 33.4, 'Nurses, taxi drivers, and restless students gradually gathered around the wooden counter.', 'Các y tá, tài xế taxi và những sinh viên trằn trọc dần tụ họp quanh quầy gỗ.', 'restless, gradually, gathered', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-7', 'lesson-audio-b1b2-01', 'owner', 33.4, 39.3, 'Rather than rushing home, strangers began exchanging stories over cups of herbal tea.', 'Thay vì vội vã về nhà, những người xa lạ bắt đầu trao đổi câu chuyện bên tách trà thảo mộc.', 'rather than, exchanging stories, herbal tea', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-8', 'lesson-audio-b1b2-01', 'owner', 39.3, 44.8, 'Daniel realized that loneliness could dissolve surprisingly quickly in the right atmosphere.', 'Daniel nhận ra rằng sự cô đơn có thể tan biến nhanh đến bất ngờ trong bầu không khí phù hợp.', 'dissolve, surprisingly, atmosphere', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-01-seg-9', 'lesson-audio-b1b2-01', 'owner', 44.8, 51.5, 'By sunrise, the little bakery had quietly transformed an isolated neighborhood into a genuine community.', 'Khi bình minh lên, tiệm bánh nhỏ đã lặng lẽ biến khu phố tách biệt thành một cộng đồng thực thụ.', 'transformed, isolated, genuine community', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-02', 'owner', 'audio-b1b2-02', '02. Why Micro-Breaks Boost Your Focus (B1-B2)', 'Discover how brief 2-minute pauses prevent cognitive fatigue and sustain productivity throughout the day (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-1', 'lesson-audio-b1b2-02', 'owner', 0, 4.6, 'Many ambitious professionals believe that working nonstop guarantees higher productivity.', 'Nhiều người đi làm đầy tham vọng tin rằng làm việc không ngừng nghỉ sẽ đảm bảo năng suất cao hơn.', 'ambitious, guarantees, productivity', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-2', 'lesson-audio-b1b2-02', 'owner', 4.6, 10.1, 'However, cognitive researchers have discovered that continuous concentration rapidly drains mental energy.', 'Tuy nhiên, các nhà nghiên cứu nhận thức phát hiện rằng sự tập trung liên tục nhanh chóng làm cạn kiệt năng lượng tinh thần.', 'cognitive, continuous, drains', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-3', 'lesson-audio-b1b2-02', 'owner', 10.1, 16, 'When you ignore early signs of fatigue, subtle mistakes become far more frequent.', 'Khi bạn phớt lờ những dấu hiệu mệt mỏi ban đầu, các sai sót nhỏ trở nên thường xuyên hơn nhiều.', 'fatigue, subtle, frequent', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-4', 'lesson-audio-b1b2-02', 'owner', 16, 21.5, 'Surprisingly, taking a two-minute micro-break every hour can restore your attention span.', 'Đáng ngạc nhiên là việc nghỉ ngắn hai phút mỗi giờ có thể phục hồi khả năng tập trung của bạn.', 'micro-break, restore, attention span', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-5', 'lesson-audio-b1b2-02', 'owner', 21.5, 27.8, 'The secret is stepping away from bright screens rather than scrolling through social media.', 'Bí quyết là rời khỏi màn hình sáng thay vì lướt mạng xã hội.', 'stepping away, scrolling', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-6', 'lesson-audio-b1b2-02', 'owner', 27.8, 34.5, 'Stretching your shoulders, gazing out a window, or sipping water allows the brain to reset.', 'Vươn vai, nhìn ra ngoài cửa sổ hoặc nhấp ngụm nước giúp não bộ thiết lập lại trạng thái.', 'gazing, sipping, reset', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-7', 'lesson-audio-b1b2-02', 'owner', 34.5, 40, 'During these brief pauses, your subconscious mind continues organizing complex information quietly.', 'Trong những quãng nghỉ ngắn này, tiềm thức của bạn tiếp tục sắp xếp thông tin phức tạp một cách lặng lẽ.', 'subconscious, organizing, complex', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-8', 'lesson-audio-b1b2-02', 'owner', 40, 46.3, 'As a result, you return to challenging tasks with renewed clarity and creative perspective.', 'Kết quả là bạn quay lại các nhiệm vụ khó với sự minh mẫn mới và góc nhìn sáng tạo.', 'renewed clarity, perspective', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-02-seg-9', 'lesson-audio-b1b2-02', 'owner', 46.3, 51.3, 'Consistent performance depends not on endless effort, but on sustainable rhythm.', 'Hiệu suất ổn định không phụ thuộc vào nỗ lực vô tận, mà dựa vào nhịp độ bền vững.', 'consistent, sustainable rhythm', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-03', 'owner', 'audio-b1b2-03', '03. A Phone Call That Changed My Career (B1-B2)', 'A personal story about picking up an unexpected phone call and overcoming hesitation (~1 min, B1-B2 — great with Phone Mode!).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-1', 'lesson-audio-b1b2-03', 'owner', 0, 5.5, 'Last Tuesday, my phone vibrated with an unfamiliar international number during lunch.', 'Thứ Ba tuần trước, điện thoại tôi rung lên với một số quốc tế lạ đúng vào giờ ăn trưa.', 'vibrated, unfamiliar', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-2', 'lesson-audio-b1b2-03', 'owner', 5.5, 11.8, 'I normally let unknown callers go to voicemail, yet something urged me to answer.', 'Tôi thường để các cuộc gọi lạ chuyển vào hộp thư thoại, nhưng điều gì đó đã thôi thúc tôi bắt máy.', 'voicemail, urged', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-3', 'lesson-audio-b1b2-03', 'owner', 11.8, 18.1, 'Due to background traffic noise, I had to concentrate carefully on every single syllable.', 'Vì tiếng ồn giao thông xung quanh, tôi phải tập trung kỹ vào từng âm tiết một.', 'background noise, concentrate, syllable', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-4', 'lesson-audio-b1b2-03', 'owner', 18.1, 24.4, 'It turned out to be the hiring director from a design studio in Melbourne.', 'Hóa ra đó là giám đốc tuyển dụng của một studio thiết kế tại Melbourne.', 'turned out to be, hiring director', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-5', 'lesson-audio-b1b2-03', 'owner', 24.4, 30.7, 'She had reviewed my online portfolio and wanted to discuss an urgent freelance project.', 'Cô ấy đã xem hồ sơ năng lực trực tuyến của tôi và muốn trao đổi về một dự án tự do khẩn cấp.', 'portfolio, urgent, freelance', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-6', 'lesson-audio-b1b2-03', 'owner', 30.7, 35.3, 'Initially, I hesitated because the tight deadline sounded somewhat overwhelming.', 'Ban đầu, tôi do dự vì hạn chót gấp gáp nghe có vẻ hơi quá sức.', 'hesitated, tight deadline, overwhelming', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-7', 'lesson-audio-b1b2-03', 'owner', 35.3, 41.2, 'Nevertheless, we negotiated reasonable milestones and clarified every technical requirement over the call.', 'Tuy nhiên, chúng tôi đã thương lượng các mốc thời gian hợp lý và làm rõ mọi yêu cầu kỹ thuật qua cuộc gọi.', 'nevertheless, negotiated, milestones, clarified', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-8', 'lesson-audio-b1b2-03', 'owner', 41.2, 46.7, 'Delivering that assignment on schedule eventually led to a permanent remote position.', 'Hoàn thành nhiệm vụ đó đúng tiến độ cuối cùng đã mang lại một vị trí làm việc từ xa chính thức.', 'on schedule, eventually, permanent', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-03-seg-9', 'lesson-audio-b1b2-03', 'owner', 46.7, 52.6, 'Sometimes a single conversation on a noisy line can redirect your entire future.', 'Đôi khi chỉ một cuộc trò chuyện qua đường dây nhiễu sóng cũng có thể chuyển hướng cả tương lai của bạn.', 'redirect, entire', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-04', 'owner', 'audio-b1b2-04', '04. The Hidden Cost of Fast Fashion (B1-B2)', 'An insightful look at why ultra-cheap clothing carries an environmental price tag and how consumers adapt (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-1', 'lesson-audio-b1b2-04', 'owner', 0, 5.5, 'Scrolling through online catalogs, consumers are constantly tempted by rock-bottom clothing prices.', 'Khi lướt các danh mục trực tuyến, người tiêu dùng liên tục bị cám dỗ bởi mức giá quần áo rẻ mạt.', 'catalogs, constantly, tempted, rock-bottom', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-2', 'lesson-audio-b1b2-04', 'owner', 5.5, 11.4, 'Fast-fashion brands release thousands of trendy items every week to encourage impulse buying.', 'Các thương hiệu thời trang nhanh tung ra hàng nghìn mẫu hợp mốt mỗi tuần để kích thích mua sắm bốc đồng.', 'trendy, encourage, impulse buying', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-3', 'lesson-audio-b1b2-04', 'owner', 11.4, 17.3, 'Unfortunately, this rapid production cycle relies heavily on synthetic fabrics and excessive water.', 'Đáng tiếc là chu kỳ sản xuất thần tốc này phụ thuộc nặng nề vào vải tổng hợp và lượng nước khổng lồ.', 'cycle, relies heavily, synthetic, excessive', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-4', 'lesson-audio-b1b2-04', 'owner', 17.3, 24, 'Because garments are cheaply stitched, many buyers discard them after only a handful of wears.', 'Vì trang phục được may ẩu với chi phí thấp, nhiều người mua vứt bỏ chúng chỉ sau vài lần mặc.', 'garments, discard, a handful of', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-5', 'lesson-audio-b1b2-04', 'owner', 24, 30.3, 'Millions of tons of textile waste end up polluting landfills and coastal ecosystems annually.', 'Hàng triệu tấn rác thải dệt may kết thúc bằng việc gây ô nhiễm bãi rác và hệ sinh thái ven biển hằng năm.', 'textile waste, landfills, ecosystems', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-6', 'lesson-audio-b1b2-04', 'owner', 30.3, 35.3, 'Growing awareness has recently inspired younger shoppers to embrace secondhand boutiques.', 'Nhận thức ngày càng tăng gần đây đã truyền cảm hứng cho người mua trẻ đón nhận các cửa hàng đồ cũ.', 'awareness, inspired, embrace, secondhand', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-7', 'lesson-audio-b1b2-04', 'owner', 35.3, 40.8, 'Investing in durable, timeless pieces often saves money over the long run.', 'Đầu tư vào những món đồ bền bỉ, vượt thời gian thường giúp tiết kiệm tiền về lâu dài.', 'durable, timeless, over the long run', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-04-seg-8', 'lesson-audio-b1b2-04', 'owner', 40.8, 46.7, 'Choosing quality over quantity is a practical step toward a more sustainable wardrobe.', 'Chọn chất lượng hơn số lượng là một bước đi thiết thực hướng tới tủ đồ bền vững hơn.', 'quality over quantity, sustainable wardrobe', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-05', 'owner', 'audio-b1b2-05', '05. Lost in Kyoto Without a Map (B1-B2)', 'What happens when your phone battery dies in a historic Japanese neighborhood and you rely on kindness (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-1', 'lesson-audio-b1b2-05', 'owner', 0, 6.3, 'When my smartphone battery suddenly died in Kyoto, I felt completely disoriented at first.', 'Khi pin điện thoại đột ngột cạn sạch ở Kyoto, ban đầu tôi cảm thấy hoàn toàn mất phương hướng.', 'disoriented, suddenly', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-2', 'lesson-audio-b1b2-05', 'owner', 6.3, 11.8, 'Narrow cobblestone alleys twisted in every direction, lined with traditional wooden teahouses.', 'Những con hẻm lát đá hẹp uốn lượn về mọi hướng, hai bên là các quán trà gỗ truyền thống.', 'cobblestone alleys, twisted, teahouses', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-3', 'lesson-audio-b1b2-05', 'owner', 11.8, 18.5, 'Without GPS navigation, I had no choice but to slow down and observe my surroundings.', 'Không có chỉ đường GPS, tôi không còn cách nào khác ngoài việc đi chậm lại và quan sát xung quanh.', 'navigation, surroundings', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-4', 'lesson-audio-b1b2-05', 'owner', 18.5, 24.8, 'At a quiet crossroads, a local shopkeeper noticed my puzzled expression and stepped outside.', 'Tại một ngã tư yên tĩnh, một chủ tiệm địa phương nhận ra vẻ bối rối của tôi và bước ra ngoài.', 'crossroads, puzzled expression', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-5', 'lesson-audio-b1b2-05', 'owner', 24.8, 31.1, 'Although we shared few common words, she sketched clear landmarks on a paper napkin.', 'Dù chúng tôi ít vốn từ chung, cô ấy vẫn phác thảo các địa điểm nổi bật rõ ràng lên tờ khăn giấy.', 'sketched, landmarks', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-6', 'lesson-audio-b1b2-05', 'owner', 31.1, 37.4, 'Following her handwritten directions, I stumbled upon a hidden bamboo courtyard untouched by crowds.', 'Đi theo chỉ dẫn viết tay của cô ấy, tôi tình cờ phát hiện một khoảng sân tre ẩn mình vắng bóng đám đông.', 'stumbled upon, courtyard, untouched', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-7', 'lesson-audio-b1b2-05', 'owner', 37.4, 43.7, 'A gentle breeze rustled the leaves while rainwater dripped softly into a stone basin.', 'Một làn gió nhẹ làm xào xạc tán lá trong khi nước mưa nhỏ giọt êm ái xuống bồn đá.', 'breeze, rustled, stone basin', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-05-seg-8', 'lesson-audio-b1b2-05', 'owner', 43.7, 50.4, 'By the time I reached the main station, getting lost had become my favorite memory.', 'Vào lúc tôi quay lại được ga chính, việc bị lạc đường đã trở thành kỷ niệm yêu thích nhất của tôi.', 'reached, memory', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-06', 'owner', 'audio-b1b2-06', '06. The Art of Polite Disagreement (B1-B2)', 'Learn diplomatic phrases and mindset shifts for expressing opposing viewpoints at work without conflict (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-1', 'lesson-audio-b1b2-06', 'owner', 0, 6.3, 'Disagreeing with a colleague in a meeting can feel awkward if not handled thoughtfully.', 'Bất đồng quan điểm với đồng nghiệp trong cuộc họp có thể gây khó xử nếu không được xử lý khéo léo.', 'colleague, awkward, thoughtfully', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-2', 'lesson-audio-b1b2-06', 'owner', 6.3, 12.2, 'Many people either stay silent to preserve harmony or argue aggressively to win.', 'Nhiều người hoặc chọn im lặng để giữ hòa khí, hoặc tranh luận gay gắt để giành phần thắng.', 'preserve harmony, aggressively', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-3', 'lesson-audio-b1b2-06', 'owner', 12.2, 17.2, 'Neither approach fosters genuine collaboration or leads to innovative team decisions.', 'Cả hai cách tiếp cận đều không nuôi dưỡng sự hợp tác thực sự hay dẫn tới các quyết định đột phá của nhóm.', 'fosters, collaboration, innovative', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-4', 'lesson-audio-b1b2-06', 'owner', 17.2, 22.7, 'Effective communicators begin by acknowledging the valid points in another person’s proposal.', 'Người giao tiếp hiệu quả bắt đầu bằng việc ghi nhận những điểm hợp lý trong đề xuất của người khác.', 'acknowledging, valid points, proposal', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-5', 'lesson-audio-b1b2-06', 'owner', 22.7, 29.4, 'Phrases like "I see where you’re coming from, though I have one concern" lower defensiveness.', 'Những cụm từ như "Tôi hiểu góc nhìn của bạn, tuy nhiên tôi có một băn khoăn" giúp giảm thái độ phòng thủ.', 'concern, defensiveness', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-6', 'lesson-audio-b1b2-06', 'owner', 29.4, 35.3, 'Focusing strictly on objective evidence rather than personal criticism keeps the discussion productive.', 'Chỉ tập trung vào bằng chứng khách quan thay vì chỉ trích cá nhân giúp cuộc thảo luận hiệu quả.', 'objective evidence, criticism, productive', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-7', 'lesson-audio-b1b2-06', 'owner', 35.3, 41.2, 'When teams welcome respectful debate, blind spots are identified before costly errors occur.', 'Khi đội ngũ hoan nghênh tranh luận tôn trọng, các điểm mù được phát hiện trước khi sai lầm tốn kém xảy ra.', 'respectful debate, blind spots, occur', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-06-seg-8', 'lesson-audio-b1b2-06', 'owner', 41.2, 46.2, 'True diplomacy transforms potential conflict into an opportunity for shared growth.', 'Sự khéo léo thực sự biến xung đột tiềm ẩn thành cơ hội cùng phát triển.', 'diplomacy, transforms, potential conflict', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-07', 'owner', 'audio-b1b2-07', '07. Why Cities Are Planting Vertical Forests (B1-B2)', 'How modern architects cover skyscrapers with thousands of trees to cool concrete cities (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-1', 'lesson-audio-b1b2-07', 'owner', 0, 5.9, 'Concrete skyscrapers trap solar heat, turning densely populated cities into scorching summer ovens.', 'Những tòa nhà chọc trời bằng bê tông giữ nhiệt mặt trời, biến các đô thị đông đúc thành lò nướng mùa hè.', 'concrete, trap, densely populated, scorching', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-2', 'lesson-audio-b1b2-07', 'owner', 5.9, 10.9, 'To combat rising urban temperatures, visionary architects are designing vertical forests.', 'Để đối phó với nhiệt độ đô thị gia tăng, các kiến trúc sư có tầm nhìn đang thiết kế những khu rừng thẳng đứng.', 'combat, urban, visionary architects', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-3', 'lesson-audio-b1b2-07', 'owner', 10.9, 17.2, 'Instead of plain glass facades, reinforced balconies hold hundreds of resilient shrubs and trees.', 'Thay vì mặt kính trơn, các ban công gia cố chứa hàng trăm cây bụi và cây thân gỗ bền bỉ.', 'facades, reinforced, resilient shrubs', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-4', 'lesson-audio-b1b2-07', 'owner', 17.2, 23.1, 'Botanists carefully select native species capable of withstanding strong winds at high altitudes.', 'Các nhà thực vật học chọn lọc kỹ những loài bản địa có khả năng chịu gió mạnh ở độ cao lớn.', 'botanists, native species, withstanding, altitudes', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-5', 'lesson-audio-b1b2-07', 'owner', 23.1, 28.6, 'This living curtain naturally filters airborne dust while absorbing substantial carbon dioxide.', 'Bức rèm sống động này tự nhiên lọc bụi trong không khí đồng thời hấp thụ lượng lớn khí carbonic.', 'airborne dust, absorbing, substantial', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-6', 'lesson-audio-b1b2-07', 'owner', 28.6, 34.1, 'Inside the apartments, natural shade reduces air-conditioning consumption by nearly thirty percent.', 'Bên trong các căn hộ, bóng râm tự nhiên giúp giảm lượng điện tiêu thụ điều hòa gần ba mươi phần trăm.', 'consumption, nearly', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-7', 'lesson-audio-b1b2-07', 'owner', 34.1, 40, 'Even better, birds and pollinators soon return, restoring fragile biodiversity to crowded districts.', 'Tuyệt vời hơn, chim chóc và côn trùng thụ phấn sớm quay trở lại, khôi phục đa dạng sinh học mong manh cho các quận đông đúc.', 'pollinators, fragile biodiversity', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-07-seg-8', 'lesson-audio-b1b2-07', 'owner', 40, 45.5, 'Green architecture proves that modern cities and thriving nature can coexist harmoniously.', 'Kiến trúc xanh chứng minh rằng đô thị hiện đại và thiên nhiên trù phú có thể cùng tồn tại hài hòa.', 'thriving, coexist harmoniously', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-08', 'owner', 'audio-b1b2-08', '08. The Mystery of the Unclaimed Suitcase (B1-B2)', 'A clever short story set in an airport baggage claim with an unexpected coincidence (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-1', 'lesson-audio-b1b2-08', 'owner', 0, 6.3, 'By midnight, the airport baggage carousel had stopped spinning, leaving only one dark suitcase.', 'Đến nửa đêm, băng chuyền hành lý sân bay đã ngừng quay, chỉ còn lại duy nhất một chiếc vali tối màu.', 'baggage carousel, spinning', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-2', 'lesson-audio-b1b2-08', 'owner', 6.3, 12.2, 'Exhausted from a delayed flight, Maya realized her own matching luggage had vanished.', 'Kiệt sức sau chuyến bay bị hoãn, Maya nhận ra chiếc hành lý giống hệt của mình đã biến mất.', 'exhausted, vanished', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-3', 'lesson-audio-b1b2-08', 'owner', 12.2, 18.9, 'She checked the leather tag and discovered the name Leo Vance alongside a phone number.', 'Cô kiểm tra thẻ hành lý bằng da và phát hiện cái tên Leo Vance cùng một số điện thoại.', 'leather tag, alongside', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-4', 'lesson-audio-b1b2-08', 'owner', 18.9, 24.4, 'Reluctant to wake a stranger, she hesitated before tapping the call button.', 'Ngần ngại đánh thức một người xa lạ, cô chần chừ trước khi bấm nút gọi.', 'reluctant, hesitated', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-5', 'lesson-audio-b1b2-08', 'owner', 24.4, 29.9, 'Moments later, a relieved voice answered from a taxi twenty minutes away.', 'Vài giây sau, một giọng nói nhẹ nhõm bắt máy từ chiếc taxi cách đó hai mươi phút chạy xe.', 'relieved voice', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-6', 'lesson-audio-b1b2-08', 'owner', 29.9, 35.4, 'Leo confessed he had grabbed the identical suitcase without inspecting the label.', 'Leo thú nhận anh đã vội lấy chiếc vali giống hệt mà không kiểm tra nhãn tên.', 'confessed, identical, inspecting', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-7', 'lesson-audio-b1b2-08', 'owner', 35.4, 41.3, 'They agreed to meet at a bright terminal café to swap their belongings.', 'Họ hẹn gặp nhau tại một quán cà phê sáng đèn trong nhà ga để trao đổi lại hành lý.', 'terminal, swap, belongings', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-8', 'lesson-audio-b1b2-08', 'owner', 41.3, 47.2, 'Over coffee, they laughed to discover both were attending the same architecture conference.', 'Bên tách cà phê, họ bật cười khi phát hiện cả hai cùng tham dự một hội nghị kiến trúc.', 'attending, conference', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-08-seg-9', 'lesson-audio-b1b2-08', 'owner', 47.2, 52.7, 'What began as an irritating travel blunder turned into an unforgettable friendship.', 'Điều khởi đầu như một sự cố du lịch bực mình lại hóa thành một tình bạn khó quên.', 'irritating, blunder, unforgettable', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-09', 'owner', 'audio-b1b2-09', '09. Digital Minimalism for Busy Minds (B1-B2)', 'Practical habits to tame nonstop notifications and reclaim calm, intentional evenings (~1 min, B1-B2).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-1', 'lesson-audio-b1b2-09', 'owner', 0, 5.9, 'Our smartphones promise convenience, yet constant notifications fragment our daily peace of mind.', 'Điện thoại thông minh hứa hẹn sự tiện lợi, nhưng thông báo liên tục lại làm vụn vỡ sự bình yên hằng ngày.', 'fragment, peace of mind', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-2', 'lesson-audio-b1b2-09', 'owner', 5.9, 12.2, 'Whenever a red badge flashes, our brain anticipates a tiny reward and loses focus.', 'Mỗi khi biểu tượng đỏ nhấp nháy, não bộ lại mong chờ một phần thưởng nhỏ và đánh mất sự tập trung.', 'anticipates, loses focus', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-3', 'lesson-audio-b1b2-09', 'owner', 12.2, 18.1, 'Digital minimalism does not require abandoning technology or moving to a remote cabin.', 'Tối giản kỹ thuật số không đòi hỏi bạn phải từ bỏ công nghệ hay chuyển lên một căn nhà gỗ hẻo lánh.', 'minimalism, abandoning, remote cabin', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-4', 'lesson-audio-b1b2-09', 'owner', 18.1, 23.6, 'Instead, it invites you to audit which applications genuinely enrich your life.', 'Thay vào đó, nó mời gọi bạn rà soát xem ứng dụng nào thực sự làm phong phú cuộc sống của mình.', 'audit, genuinely enrich', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-5', 'lesson-audio-b1b2-09', 'owner', 23.6, 29.5, 'Start by muting non-essential alerts and removing distracting apps from your home screen.', 'Hãy bắt đầu bằng việc tắt các cảnh báo không thiết yếu và gỡ bỏ ứng dụng gây xao nhãng khỏi màn hình chính.', 'non-essential alerts, distracting', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-6', 'lesson-audio-b1b2-09', 'owner', 29.5, 35.4, 'Establishing a phone-free hour before bedtime dramatically improves both sleep quality and mood.', 'Thiết lập một giờ không điện thoại trước khi ngủ giúp cải thiện rõ rệt cả chất lượng giấc ngủ lẫn tâm trạng.', 'establishing, dramatically improves', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-7', 'lesson-audio-b1b2-09', 'owner', 35.4, 41.3, 'Without endless scrolling, evenings suddenly stretch longer, leaving room for reading or cooking.', 'Không còn lướt màn hình vô tận, buổi tối bỗng dưng dài ra, nhường chỗ cho việc đọc sách hoặc nấu ăn.', 'stretch longer, leaving room', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-09-seg-8', 'lesson-audio-b1b2-09', 'owner', 41.3, 48, 'When you control your attention deliberately, technology becomes a helpful servant rather than a master.', 'Khi bạn kiểm soát sự chú ý một cách có chủ đích, công nghệ trở thành trợ thủ đắc lực thay vì làm chủ bạn.', 'deliberately, servant', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-b1b2-10', 'owner', 'audio-b1b2-10', '10. Customer Support Call: Flight Delay (B1-B2)', 'A realistic customer-service phone call resolving a cancelled flight & rebooking (~1 min, B1-B2 — try Phone Call Mode!).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-1', 'lesson-audio-b1b2-10', 'owner', 0, 6.3, 'Good evening, thank you for calling Horizon Airlines support; how may I assist you?', 'Chào buổi tối, cảm ơn quý khách đã gọi đến tổng đài Horizon Airlines; tôi có thể hỗ trợ gì cho bạn?', 'assist', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-2', 'lesson-audio-b1b2-10', 'owner', 6.3, 11.8, 'Hi, my connecting flight to Chicago was cancelled due to severe storms.', 'Chào bạn, chuyến bay nối chuyến đi Chicago của tôi đã bị hủy do bão lớn.', 'connecting flight, severe storms', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-3', 'lesson-audio-b1b2-10', 'owner', 11.8, 17.7, 'I need to attend an important client presentation tomorrow morning at nine sharp.', 'Tôi cần tham dự một buổi thuyết trình quan trọng với khách hàng vào đúng chín giờ sáng mai.', 'presentation, nine sharp', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-4', 'lesson-audio-b1b2-10', 'owner', 17.7, 23.2, 'Certainly, let me pull up your itinerary using your six-letter booking reference.', 'Chắc chắn rồi, để tôi tra cứu lịch trình của bạn bằng mã đặt chỗ sáu ký tự.', 'itinerary, booking reference', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-5', 'lesson-audio-b1b2-10', 'owner', 23.2, 29.1, 'I see two available seats on an alternative departure leaving at six-fifteen tomorrow.', 'Tôi thấy còn hai ghế trống trên một chuyến bay thay thế khởi hành lúc sáu giờ mười lăm sáng mai.', 'alternative departure', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-6', 'lesson-audio-b1b2-10', 'owner', 29.1, 35.4, 'That works well, though could you verify whether my checked luggage will transfer automatically?', 'Giờ đó rất ổn, nhưng bạn có thể xác nhận giúp hành lý ký gửi của tôi có tự động chuyển sang không?', 'verify, checked luggage, transfer', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-7', 'lesson-audio-b1b2-10', 'owner', 35.4, 42.9, 'Yes, your baggage is tagged for the final destination, and we are providing a hotel voucher tonight.', 'Có ạ, hành lý đã được gắn thẻ tới điểm đến cuối cùng, và chúng tôi sẽ cấp phiếu khách sạn cho bạn tối nay.', 'final destination, voucher', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-8', 'lesson-audio-b1b2-10', 'owner', 42.9, 49.6, 'I truly appreciate your prompt assistance; could you email the updated boarding pass right away?', 'Tôi thực sự cảm kích sự hỗ trợ nhanh chóng của bạn; bạn có thể gửi thẻ lên máy bay mới qua email ngay không?', 'prompt assistance, boarding pass', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-b1b2-10-seg-9', 'lesson-audio-b1b2-10', 'owner', 49.6, 56.3, 'It is already in your inbox, and we wish you a smooth, punctual journey tomorrow.', 'Thư đã nằm trong hộp thư đến của bạn rồi ạ, chúc bạn ngày mai có một chuyến đi suôn sẻ và đúng giờ.', 'smooth, punctual journey', 8);
